import java.util.List;
import java.util.Scanner;

// Capa de Vista encargada exclusivamente de la interacción de entrada/salida por texto con el usuario
public class ConsolaView {
    private Scanner scanner;

    public ConsolaView() {
        this.scanner = new Scanner(System.in);
    }

    // Muestra las opciones principales del menú por consola y captura la selección
    public int mostrarMenuPrincipal() {
        System.out.println("\n--- SISTEMA DE INTEGRACIONES EXTERNAS (MVC) ---");
        System.out.println("1. Listar todas las integraciones");
        System.out.println("2. Ordenar integraciones por latencia (Natural Order)");
        System.out.println("3. Buscar integración por ID");
        System.out.println("4. Registrar nueva integración"); 
        System.out.println("5. Salir");                        
        System.out.print("Seleccione una opción: ");
        return scanner.nextInt();
    }

    // Recorre e imprime de forma polimórfica los detalles de los elementos del catálogo
    public void mostrarListaIntegraciones(List<AbstractIntegracion> integraciones) {
        System.out.println("\n--- LISTA DE INTEGRACIONES ---");
        for (AbstractIntegracion i : integraciones) {
            System.out.println(i.mostrarDetalles() + " | Latencia: " + i.getLatenciaPromedioMs() + "ms | Estado: " + i.getEstadoConexion());
        }
    }

    public void mostrarMensaje(String mensaje) {
        System.out.println(mensaje);
    }

    // Solicita un texto por consola limpiando correctamente el buffer del scanner
    public String pedirInput(String invitacion) {
        System.out.print(invitacion);
        scanner.nextLine(); // Limpieza del buffer pendiente
        return scanner.nextLine();
    }

    // Método interactivo para solicitar los datos y construir una nueva integración polimórfica
    public AbstractIntegracion solicitarNuevaIntegracion() {
        System.out.println("\n--- REGISTRAR NUEVA INTEGRACIÓN ---");
        System.out.println("¿Qué tipo de integración desea agregar?");
        System.out.println("1. Pasarela de Tarjeta de Crédito");
        System.out.println("2. Proveedor de Logística de Envíos");
        System.out.print("Seleccione una opción: ");
        int tipo = scanner.nextInt();
        scanner.nextLine(); // Limpiar el buffer de entrada

        System.out.print("Ingrese ID único (ej. TC-03 o ENV-03): ");
        String id = scanner.nextLine();
        System.out.print("Ingrese Nombre del Proveedor: ");
        String nombre = scanner.nextLine();
        System.out.print("Ingrese Estado de Conexión (ej. ACTIVO): ");
        String estado = scanner.nextLine();
        System.out.print("Ingrese Latencia Promedio (ms): ");
        double latencia = scanner.nextDouble();
        scanner.nextLine(); // Limpiar el buffer de entrada

        // Retorna una instancia concreta según la selección del usuario (demostrando polimorfismo)
        if (tipo == 1) {
            System.out.print("Ingrese Tipo de Tarjeta (ej. Crédito/Débito): ");
            String tipoTarjeta = scanner.nextLine();
            return new PasarelaTarjetaCredito(id, nombre, estado, latencia, tipoTarjeta);
        } else {
            System.out.print("Ingrese Zona de Cobertura: ");
            String zona = scanner.nextLine();
            System.out.print("¿Es última milla? (true/false): ");
            boolean ultimaMilla = scanner.nextBoolean();
            return new ProveedorLogisticaEnvio(id, nombre, estado, latencia, zona, ultimaMilla);
        }
    }
}